import heapq
from typing import Dict, List, Any, Set, Iterable

def stable_toposort(graph: Dict[Any, Iterable[Any]]) -> List[Any]:
    """
    Return a dependency-first ordering of nodes in `graph`.

    The graph maps each node to an iterable of its dependencies.
    Ties in readiness are broken by the original insertion order of nodes
    in the dictionary. Raises ValueError if a dependency is missing or if
    a cycle exists. The input dictionary is not mutated.
    """
    # Check for missing dependencies and build maps
    nodes = list(graph.keys())             # preserve insertion order
    index_map = {node: i for i, node in enumerate(nodes)}

    # Verify all dependencies exist
    for node, deps in graph.items():
        for dep in deps:
            if dep not in index_map:
                raise ValueError(f"Missing dependency: {dep} (required by {node})")

    # Compute indegrees and dependents adjacency
    indegree = {node: 0 for node in nodes}
    dependents: Dict[Any, List[Any]] = {node: [] for node in nodes}
    for node, deps in graph.items():
        deps_list = list(deps)  # ensure iterable is reusable
        indegree[node] = len(deps_list)
        for dep in deps_list:
            dependents[dep].append(node)

    # Initialize heap with nodes having zero indegree
    heap = []
    for node in nodes:
        if indegree[node] == 0:
            heapq.heappush(heap, (index_map[node], node))

    result = []
    while heap:
        idx, node = heapq.heappop(heap)
        result.append(node)
        for dep in dependents[node]:
            indegree[dep] -= 1
            if indegree[dep] == 0:
                heapq.heappush(heap, (index_map[dep], dep))

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in graph")

    return result
```

