def merge_payload_ranges(items):
    # Filter out invalid ranges (start > end)
    valid = [(s, e, p) for s, e, p in items if s <= e]
    # Sort by start, then end
    valid.sort(key=lambda x: (x[0], x[1]))

    result = []
    for start, end, payload in valid:
        if not result:
            result.append([start, end, payload])
            continue

        last = result[-1]
        # Merge if payload same and intervals overlap or touch
        if payload == last[2] and start <= last[1] + 1:
            if end > last[1]:
                last[1] = end
        else:
            result.append([start, end, payload])

    return result
